snmplib/snmp_api.c:696:_init_snmp(void)
   690   * SNMP over AppleTalk is not currently supported.
   691   *
   692   * Warning: no debug messages here.
   693   */
   694  static char _init_snmp_init_done = 0;
   695  static void
   696  _init_snmp(void)
   697  {
   698
   699      struct timeval  tv;
   700      long            tmpReqid, tmpMsgid;
   701
   702      if (_init_snmp_init_done)
   703          return;
   704      _init_snmp_init_done = 1;
   705      Reqid = 1;
   706
   707      snmp_res_init();            /* initialize the mt locking structures */
   708  #ifndef NETSNMP_DISABLE_MIB_LOADING
   709      netsnmp_init_mib_internals();
   710  #endif /* NETSNMP_DISABLE_MIB_LOADING */
   711      netsnmp_tdomain_init();
   712
   713      gettimeofday(&tv, (struct timezone *) 0);
   714      /*
   715       * Now = tv;
   716       */
   717
   718      /*
   719       * get pseudo-random values for request ID and message ID
   720       */
   721      netsnmp_srandom((unsigned)(tv.tv_sec ^ tv.tv_usec));
   722      tmpReqid = netsnmp_random();
   723      tmpMsgid = netsnmp_random();
   724
   725      /*
   726       * don't allow zero value to repeat init
   727       */
   728      if (tmpReqid == 0)
   729          tmpReqid = 1;
   730      if (tmpMsgid == 0)
   731          tmpMsgid = 1;
   732      Reqid = tmpReqid;
   733      Msgid = tmpMsgid;
   734
   735      netsnmp_register_default_domain("snmp", "udp udp6");
   736      netsnmp_register_default_domain("snmptrap", "udp udp6");
   737
   738      netsnmp_register_default_target("snmp", "udp", ":161");
   739      netsnmp_register_default_target("snmp", "tcp", ":161");
   740      netsnmp_register_default_target("snmp", "udp6", ":161");
